import pathlib,json,hashlib,math,statistics,subprocess,shutil,os
O=pathlib.Path(__file__).resolve().parent.parent;Q=O/'replay';Q.mkdir(exist_ok=True);R_SCRIPT=os.environ.get('RSCRIPT') or shutil.which('Rscript');assert R_SCRIPT, 'Existing Rscript required; this runner never installs software'
def h(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
pp=O/'data/IMPACT_AUDIT_PLAN.json';rp=O/'replay/PUBLISHED_INPUT_IMPACT_AUDIT.json';ip=O/'data/PUBLISHED_FIGURE_ROWS_REUSED.json';cp=O/'scripts/run_impact_audit.R'
plan=json.load(open(pp));published=json.load(open(rp));base=json.load(open(O/'data/INDEPENDENT_TRANSCRIBED_REFERENCE_ROWS.json'))['competitor_figure2']['transcribed_rows']
# Independent numerical core: optimize the scalar intercept-only REML negative log likelihood directly.
def wstats(y,v,tau2):
 w=[1/(a+tau2) for a in v];sw=sum(w);mu=sum(a*b for a,b in zip(w,y))/sw;res=sum(a*(b-mu)**2 for a,b in zip(w,y));return w,sw,mu,res
def objective(tau2,y,v):
 w,sw,mu,res=wstats(y,v,tau2)
 return .5*(sum(math.log(a+tau2) for a in v)+math.log(sw)+res)
def golden(y,v):
 sy=sum((a-sum(y)/len(y))**2 for a in y)/max(1,len(y)-1);lo=0.;hi=max(100.,sy*30)
 g=(math.sqrt(5)-1)/2;c=hi-g*(hi-lo);d=lo+g*(hi-lo);fc=objective(c,y,v);fd=objective(d,y,v)
 for _ in range(220):
  if fc<fd:
   hi=d;d=c;fd=fc;c=hi-g*(hi-lo);fc=objective(c,y,v)
  else:
   lo=c;c=d;fc=fd;d=lo+g*(hi-lo);fd=objective(d,y,v)
 mid=(lo+hi)/2
 return 0. if objective(0,y,v)<=objective(mid,y,v) else mid
# R base supplies only t quantiles; estimation, weights, residual q, SE and intervals are independently assembled in Python.
dfs=sorted(set(len([r for r in base if r['label'] not in s['drop']])-i for s in plan['scenarios'] for i in [1,2]))
expr='cat(paste(format(qt(.975,c('+','.join(map(str,dfs))+')),digits=17),collapse=","))'
qt={df:val for df,val in zip(dfs,map(float,subprocess.check_output([R_SCRIPT,'-e',expr],text=True).split(',')))}
z=statistics.NormalDist().inv_cdf(.975);checks=[];errors=[]
for s in plan['scenarios']:
 rows=[]
 for r in base:
  if r['label'] in s['drop']:continue
  r=dict(r);u=s['N_updates'].get(r['label'],{});ni=u.get('I',r['N_I_displayed']);nc=u.get('C',r['N_C_displayed']);su=s.get('SD_updates',{}).get(r['label'],{});r['SD_I']=su.get('I',r['SD_I']);r['SD_C']=su.get('C',r['SD_C']);rows.append({'label':r['label'],'mean_I':r['mean_I'],'SD_I':r['SD_I'],'N_I':ni,'mean_C':r['mean_C'],'SD_C':r['SD_C'],'N_C':nc,'yi':r['mean_I']-r['mean_C'],'vi':r['SD_I']**2/ni+r['SD_C']**2/nc})
 m=len(rows);y=[r['yi'] for r in rows];v=[r['vi'] for r in rows];wf,swf,muf,Qf=wstats(y,v,0);sef=1/math.sqrt(swf);tau=golden(y,v);wr,swr,mur,res=wstats(y,v,tau);qraw=res/(m-1);q=max(1.,qraw);ser=math.sqrt(q/swr);cir=[mur-qt[m-1]*ser,mur+qt[m-1]*ser];pir=[mur-qt[m-2]*math.sqrt(tau+ser**2),mur+qt[m-2]*math.sqrt(tau+ser**2)]
 inp=published['scenario_inputs'][s['id']];iref={r['label']:r for r in inp};input_ok=len(inp)==m and all(r['label'] in iref and abs(r['yi']-iref[r['label']]['yi'])<1e-12 and abs(r['vi']-iref[r['label']]['vi'])<1e-12 and r['N_I']==iref[r['label']]['displayed_N_I'] and r['N_C']==iref[r['label']]['displayed_N_C'] for r in rows)
 pr=published['results'][s['id']];f=pr['fixed'];re=pr['random_REML_modified_HK'];tauerr=abs(tau-re['tau2']);maxval=max(abs(mur-re['estimate']),abs(ser-re['se']),*(abs(a-b) for a,b in zip(cir,re['ci'])),*(abs(a-b) for a,b in zip(pir,re['diagnostic_prediction_interval'])))
 fixed_ok=max(abs(muf-f['estimate']),abs(sef-f['se']),abs(Qf-f['Q']),*(abs(a-b) for a,b in zip([muf-z*sef,muf+z*sef],f['ci'])))<1e-9
 rowsk_ok=pr['source_effect_rows']==m and pr['independent_trial_k'] is None and not pr['valid_clinical_pool'] and not pr['project_primary_model']
 ok=input_ok and fixed_ok and tauerr<.0002 and maxval<.00002 and rowsk_ok
 if not ok:errors.append({'scenario':s['id'],'input_ok':input_ok,'fixed_ok':fixed_ok,'tau_error':tauerr,'max_random_value_error':maxval,'row_semantics_ok':rowsk_ok})
 checks.append({'scenario_id':s['id'],'m_effect_rows':m,'independent_trial_k':None,'canonical_independent_input_sha256':hashlib.sha256(json.dumps(rows,sort_keys=True,separators=(',',':')).encode()).hexdigest(),'intended_inputs_match_saved_scenario':input_ok,'fixed_independent':{'mu':muf,'se':sef,'CI95':[muf-z*sef,muf+z*sef],'Q':Qf},'REML_independent_scalar_optimum':{'tau2':tau,'mu':mur,'q_HK_raw':qraw,'q_HK_modified':q,'se_mHK':ser,'df':m-1,'CI95':cir,'diagnostic_PI95':pir},'tau2_abs_difference_from_metafor':tauerr,'max_mu_SE_CI_PI_abs_difference_from_metafor':maxval,'wrong_QE_based_q_counterexample':Qf/(m-1),'q_is_RE_residual_based_not_QE':abs(qraw-Qf/(m-1))>1e-5,'row_counts_and_null_k_labels_correct':rowsk_ok,'pass':ok})
code=cp.read_text();current_formula_ok='q_hk_raw <- sum(w_re*(d$yi-as.numeric(fit_r$b))^2)/(m-1)' in code and 'q_hk <- max(1,q_hk_raw)' in code and 'sqrt(q_hk_raw/sum(w_re))' in code
assert len(checks)==len(plan['scenarios'])
out={'date_local':'2026-10-29','verifier':'evidence_audit independent AI numerical/method review, not human review','status':'pass_for_bounded_published_row_diagnostic_only' if not errors and current_formula_ok else 'differences_require_review','source_files':[{'path':str(p.relative_to(O)),'sha256':h(p)} for p in [pp,rp,ip,cp]],'independent_method':'Independently transcribed Figure2 rows from prior own visual check; independently apply plan changes; fixed IV arithmetic; direct scalar minimization of intercept-only REML negative restricted log likelihood =.5[Σlog(vi+tau²)+logΣw+Σw(yi−mu)²]; REweights, q, mHK and PI assembled in Python. R base only supplies Student-t quantiles, no metafor in independent estimation.','checked_scenario_count':len(checks),'scenario_checks':checks,'errors_found':errors,'current_code_formula_check':{'current_RE_residual_q_formula_verified':current_formula_ok,'current_script_checks_raw_HK_SE_against_metafor_knha_SE':True,'all_current_scenarios_q_greater_than_1':all(c['REML_independent_scalar_optimum']['q_HK_raw']>1 for c in checks),'q_floor_exercised_scenario_ids':[c['scenario_id'] for c in checks if c['REML_independent_scalar_optimum']['q_HK_raw']<1], 'q_floor_branch_checked_numerically':any(c['REML_independent_scalar_optimum']['q_HK_raw']<1 for c in checks),'prior_code_issue_record':'Parent reported that an initial code draft used metafor$QE for HK. This auditor verifies the corrected current code, independently reproduces current q≈1.01–1.11 and demonstrates QE/(m−1) would be materially different. The obsolete draft was not independently inspected and is not treated as a scientific scenario/result.','data_and_scenarios_redefined_due_to_code_correction':False},'interpretation_and_design_limits':['m denotes displayed effect rows, not independent studies. Current null independent_trial_k and false valid_clinical_pool labels are correct.','S0 restores5.31[4.87,5.75] under the displayed fixed IV convention; this does not validate source means, scales, paired-change SDs, N, comparisons or author workflow.','Correlated multiarm contrasts, overlapping Nazarpour reports and source precision/measurement issues remain unresolved in these scalar independent-row models. Hence neither HK intervals nor PI have certified clinical coverage.','N-only scenarios retain the original displayed dispersion and effect; they diagnose the isolated effect of changing denominators, not the true corrected trial effect/precision or ITT.','S5b intentionally changes both the report retained and its I N48→47. It is a documented report-selection-plus-N path, not a pure single-numeric-factor deletion contrast; do not attribute its full shift to report removal alone.','Dropping a suspicious source row from a diagnostic calculation is not formal exclusion of that trial from the systematic review.','Prediction intervals use t(m−2) and the declared plug-in tau²+mHKmeanvariance approximation, without full tau uncertainty; they are diagnostic arithmetic and not predictions for a clinical population.','No combined corrected clinical model, final independent-trial count, confirmed MID/benefit, RoB2 or GRADE follows from these checks.'],'N_only_variance_source_readiness':'Pourkhiz/Citak original N reviewed by another AI source route; this independent numerical audit checks plan application, not a second complete extraction of those trial Ns.','posthoc_followup':'S6 originalLopes CAT23/IAT22 mean–N binding checked against source D09; variance still displayed/assumed and sharedcontrol unresolved. S7 Citakpaired-t conditionalprecision is checked here for plan-application/numericalcalculation, with source qualification from anotherAI route, not a second complete rawPDF extraction. S6–S9 are explicitly posthoc additions after the first seven diagnostic results were visible. CurrentS8 holds outBahmani two rows andS9 holds outBahmani/Hossini four rows under the same standardFSFI19 original-unit compatibility gate; sourceauthor callsBahmani instrumentFSFI19 with0–4answers, not a verifieddifferentnonFSFIinstrument. RemainingN,variance,dependence,selectionandclinicalpooling problems persist.','project_models_modified':False,'formal_human_eligibility':None,'formal_GRADE':None,'whole_SR_final_K':None}
(Q/'INDEPENDENT_IMPACT_CHECK.json').write_text(json.dumps(out,ensure_ascii=False,indent=2));print(json.dumps({'status':out['status'],'scenarios':len(checks),'current_q_formula_pass':current_formula_ok,'errors':errors,'max_tau_error':max(c['tau2_abs_difference_from_metafor'] for c in checks),'max_effect_SE_CI_PI_error':max(c['max_mu_SE_CI_PI_abs_difference_from_metafor'] for c in checks)},ensure_ascii=False))
